{
  "rule_name": "rule_operator_activity_context",
  "file": "/mnt/data/LSF/rules/nopv/agentic_rule_full_data_gpt54_adaptive/all_docs/q07_under_which_49_cfr_part_is_the_operators_regulated_activity_/rule_operator_activity_context.py",
  "code": "import re\n\n\n_ACTIVITY_RE = re.compile(\n    r\"\\b(?:hazardous\\s+liquid|liquefied\\s+natural\\s+gas|LNG(?:\\s+facility|\\s+plant)?|\"\n    r\"drug\\s+and\\s+alcohol|anti-drug|alcohol\\s+misuse|covered\\s+function|covered\\s+employee|\"\n    r\"D&A\\s+Program|gas\\s+transmission|gas\\s+distribution|distribution\\s+system|\"\n    r\"transmission\\s+pipeline|transmission\\s+line|gathering\\s+pipeline|gathering\\s+system|\"\n    r\"underground\\s+natural\\s+gas\\s+storage|control\\s+room\\s+management|\"\n    r\"National\\s+Registry\\s+of\\s+Operators|annual\\s+report|incident\\s+report)\\b\",\n    re.IGNORECASE,\n)\n_INTRO_RE = re.compile(\n    r\"\\b(?:inspected|inspection|reviewed|audit(?:ed)?|investigat(?:ed|ion)|records|procedures)\\b\",\n    re.IGNORECASE,\n)\n_ALLEGATION_RE = re.compile(\n    r\"\\b(?:item[s]?\\s+inspected|probable\\s+violation[s]?|pipeline\\s+safety\\s+regulations)\\b\",\n    re.IGNORECASE,\n)\n_PART_RE = re.compile(\n    r\"\\b(?:49\\s*C\\.?\\s*F\\.?\\s*R\\.?\\s*)?(?:Part|part)\\s*(191|192|193|195|199)\\b|\"\n    r\"(?<!\\d)(191|192|193|195|199)\\.\\d{1,4}(?:\\([a-z0-9]+\\))*\",\n    re.IGNORECASE,\n)\n\n\ndef rule_operator_activity_context(doc: dict) -> list[dict]:\n    try:\n        def norm(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\")).strip()\n\n        paragraphs = [\n            item for item in (doc.get(\"paragraphs\") or []) if isinstance(item, dict) and norm(item.get(\"text\") or \"\")\n        ]\n        if not paragraphs:\n            pages = [item for item in (doc.get(\"pages\") or []) if isinstance(item, dict) and norm(item.get(\"text\") or \"\")]\n            if not pages:\n                return []\n            text = norm(pages[0].get(\"text\") or \"\")\n            if not (_ACTIVITY_RE.search(text) or _PART_RE.search(text)):\n                return []\n            span = {\"text\": text}\n            if pages[0].get(\"page_no\") is not None:\n                span[\"page_no\"] = pages[0][\"page_no\"]\n            return [span]\n\n        scan_limit = min(len(paragraphs), 80)\n        candidates = []\n        seen = set()\n\n        for i in range(scan_limit):\n            for width in (1, 2, 3):\n                if i + width > scan_limit:\n                    break\n                chunk_items = paragraphs[i : i + width]\n                text = \"\\n\".join(norm(item.get(\"text\") or \"\") for item in chunk_items)\n                compact = norm(text)\n                if not compact:\n                    continue\n\n                has_activity = bool(_ACTIVITY_RE.search(compact))\n                has_intro = bool(_INTRO_RE.search(compact))\n                has_allegation = bool(_ALLEGATION_RE.search(compact))\n                has_part = bool(_PART_RE.search(compact))\n\n                if not has_activity:\n                    continue\n                if not (has_intro or has_allegation or has_part or i < 10):\n                    continue\n\n                rank = 4\n                if has_part and has_activity:\n                    rank = 0\n                elif has_intro and has_activity:\n                    rank = 1\n                elif has_allegation and has_activity:\n                    rank = 2\n                elif i < 10:\n                    rank = 3\n\n                key = compact.lower()\n                if key in seen:\n                    continue\n                seen.add(key)\n\n                span = {\"text\": text}\n                for field in (\"page_no\", \"paragraph_no\"):\n                    value = chunk_items[0].get(field)\n                    if value is not None:\n                        span[field] = value\n\n                candidates.append((rank, len(compact), i, span))\n\n        candidates.sort()\n        return [item[-1] for item in candidates[:3]]\n    except Exception:\n        return []\n",
